            set_cell(p, off+8, 1, 'C-5', 2, 46)
            set_cell(p, off+4, 12, 'C-5', 13, 24)
            set_cell(p, off+12, 12, 'C-5', 13, 24)
            for r in (2,6,10,14): set_cell(p, off+r, 2, 'C-5', 3, 26)"""
